import {skeletonCards} from './appearance.js';
import {createPersonSuggestions} from './suggestions.js';
import {createCardPreloader,preloadPoster} from './preload.js';
import {escapeHTML as e} from './core.js';
export function filterFilmography(movies,{role='',kind='',query='',yearFrom='',yearTo='',sort='newest',excludeWatched=false}={}){const norm=t=>String(t||'').toLowerCase().replaceAll('ё','е');const list=movies.filter(m=>(!excludeWatched||!m.watched)&&(!role||m.roles?.includes(role))&&(!kind||m.kind===kind)&&(!query||norm(m.title+' '+m.original_title).includes(norm(query)))&&(!yearFrom||m.year&&m.year>=Number(yearFrom))&&(!yearTo||m.year&&m.year<=Number(yearTo)));return list.sort((a,b)=>sort==='source'?(a.rank??Infinity)-(b.rank??Infinity):sort==='title'?a.title.localeCompare(b.title,'ru'):a.year&&b.year?(sort==='oldest'?a.year-b.year:b.year-a.year)||a.title.localeCompare(b.title,'ru'):a.year?-1:b.year?1:0);}
export function randomSelection(movies,count=3,rng=Math.random){const rows=[...new Map(movies.map(m=>[m.imdb_id,m])).values()];for(let i=rows.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[rows[i],rows[j]]=[rows[j],rows[i]];}return rows.slice(0,count);}
export function createExploreUI({request,onSearch,onWant}){
 const s={mode:'people',query:'',people:[],data:null,movies:[],collections:[],busy:false,error:'',filters:{role:'',kind:'',query:'',yearFrom:'',yearTo:'',sort:'newest'},limit:12,epoch:0,selection:null,excludeWatched:true};let collectionsLoaded=false;const pending=new Set(),applied=new WeakSet();let warmVersion=0,warmError='';const preloader=createCardPreloader({details:ids=>request('/api/discover/details',{method:'POST',body:{ids}}),poster:preloadPoster});
 const host=()=>document.querySelector('#explore-root');
 const suggestions=createPersonSuggestions({search:(query,signal)=>request('/api/explore/people?'+new URLSearchParams({query}),{signal}),onChange:renderSuggestions});
 const opt=(v,label,current)=>`<option value="${e(v)}" ${v===current?'selected':''}>${e(label)}</option>`;
 const roleName=r=>r==='director'?'Режиссёр':'Актёр / озвучивание';
 function people(){return s.people.length?`<div class="people-grid">${s.people.map(p=>`<button type="button" class="person-card" data-explore="person" data-id="${e(p.id)}"><span class="person-monogram" aria-hidden="true">${e(p.name.split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</span><span><strong>${e(p.name)}</strong><span class="person-description">${e(p.description)}${p.birthYear?` · ${e(p.birthYear)}`:''}</span><span class="person-link">Открыть фильмографию →</span></span></button>`).join('')}</div>`:'';}
 function collections(){return [['popular','Популярное сейчас','Обновляемые списки каталога'],['themes','Тематические подборки','Редакционный выбор для разного настроения'],['critics','Выбор критиков','Кино, к которому возвращаются'],['awards','Фестивали и премии','Фильмы с большими наградами']].map(([group,title,subtitle])=>`<section class="collection-section"><h3>${title}</h3><p class="help">${subtitle}</p><div class="collection-grid">${s.collections.filter(c=>c.group===group||group==='awards'&&!c.group).map(c=>`<button type="button" class="collection-card ${group==='popular'?'popular':group==='themes'?'themes':group==='critics'?'critics':'oscar'}" data-explore="collection" data-id="${e(c.id)}"><span class="collection-symbol" aria-hidden="true">${group==='popular'?'↗':group==='themes'?'◈':group==='critics'?'✧':'★'}</span><strong>${e(c.title)}</strong><span>${e(c.description)}</span><small>${e(c.source)}${c.count?` · ${c.count} фильмов`:''}</small></button>`).join('')}</div></section>`).join('');}
 function visibleMovies(){const list=filterFilmography(s.movies,{...s.filters,excludeWatched:s.excludeWatched});return s.selection?list.filter(m=>s.selection.includes(m.imdb_id)).sort((a,b)=>s.selection.indexOf(a.imdb_id)-s.selection.indexOf(b.imdb_id)):list;}
 function movieCard(m){const desc=m.ruDescription||m.description,ru=!!m.ruDescription||m.descriptionLanguage==='ru';return `<article class="explore-movie" data-movie="${e(m.imdb_id)}"><div class="discover-movie-head"><div class="discover-poster"><span class="poster-placeholder" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="m10 8 6 4-6 4z"/></svg><small>${preloader.get(m.imdb_id)?.posterReady===false?'Нет обложки':'Обложка'}</small></span><img data-explore-poster loading="${preloader.isReady([m.imdb_id])?'eager':'lazy'}" ${preloader.get(m.imdb_id)?.posterReady===false?'hidden':''} alt="" src="/api/discover/poster/${e(m.imdb_id)}"></div><div><p class="explore-movie-meta">${s.data?.collection&&m.rank?`№ ${m.rank} · `:''}${m.year||'Год не указан'} · ${m.kind==='series'?'Сериал':'Фильм'}${m.rating!==null&&m.rating!==undefined?` · IMDb ${e(m.rating)}`:''}</p><h3>${e(m.title)}</h3>${m.runtimeMinutes?`<p class="meta">${e(m.runtimeMinutes)} мин</p>`:''}${m.original_title!==m.title?`<p class="meta">${e(m.original_title)}</p>`:''}${m.roles?.length?`<p class="explore-roles">${e(m.roles.map(roleName).join(' · '))}</p>`:''}</div></div><details data-explore-detail="${e(m.imdb_id)}"><summary>О фильме</summary><p class="help">${ru?e(desc):pending.has(m.imdb_id)?'Загружаем русское описание…':desc?`Русское описание пока недоступно. ${e(desc)}`:preloader.isReady([m.imdb_id])?'Описание у источника пока недоступно.':'Загружаем данные…'}</p>${ru&&(m.descriptionURL||m.wikiURL)?`<a class="discover-imdb" href="${e(m.descriptionURL||m.wikiURL)}" target="_blank" rel="noopener noreferrer">${e(m.descriptionSource||'Википедия')} ↗</a>`:''}${m.tmdbGenres?.length?`<p class="help">${e(m.tmdbGenres.join(' · '))}</p>`:''}${m.directors?.length?`<p class="help">Режиссёр: ${e(m.directors.join(', '))}</p>`:''}${m.cast?.length?`<p class="help">В ролях: ${e(m.cast.join(', '))}</p>`:''}</details><div class="explore-movie-actions"><button class="secondary small" type="button" data-explore="release" data-id="${e(m.imdb_id)}">Найти раздачи</button><button class="explore-seen" type="button" data-explore="seen" data-id="${e(m.imdb_id)}" ${m.watched?'disabled':''}>${m.watched?'✓ Просмотрено':'Смотрел'}</button><button class="secondary outline small" type="button" data-explore="want" data-id="${e(m.imdb_id)}">Хочу посмотреть</button><a href="https://www.imdb.com/title/${e(m.imdb_id)}/" target="_blank" rel="noopener noreferrer">IMDb ↗</a></div></article>`;}
 function filmography(){if(!s.data)return '';const filtered=visibleMovies(),title=s.data.person?.name||s.data.collection?.title;return `<div class="filmography-heading"><button type="button" class="explore-back" data-explore="back">← ${s.mode==='people'?'К персонам':'К подборкам'}</button><p class="eyebrow">${s.data.person?'ФИЛЬМОГРАФИЯ':'ПОДБОРКА'}</p><h2>${e(title)}</h2>${s.data.person?.description?`<p class="help">${e(s.data.person.description)}</p>`:''}<p class="help">${s.movies.length} работ по данным источника${s.data.stale?' · сохранённая копия':''}</p></div>${s.data.collection?'<details class="collection-filter-panel"><summary>Фильтры и сортировка</summary>':''}<form id="filmography-filters"><label class="field"><span>Найти в списке</span><input name="query" value="${e(s.filters.query)}" placeholder="Название фильма" autocomplete="off"></label><div class="explore-filter-grid">${s.data.person?`<label class="field"><span>Участие</span><select name="role">${opt('','Все работы',s.filters.role)}${opt('actor','Актёр / озвучивание',s.filters.role)}${opt('director','Режиссёр',s.filters.role)}</select></label>`:''}<label class="field"><span>Тип</span><select name="kind">${opt('','Фильмы и сериалы',s.filters.kind)}${opt('movie','Фильмы',s.filters.kind)}${opt('series','Сериалы',s.filters.kind)}</select></label><label class="field"><span>Год от</span><input name="yearFrom" inputmode="numeric" type="number" min="1870" max="2100" value="${e(s.filters.yearFrom)}" placeholder="Любой"></label><label class="field"><span>Год до</span><input name="yearTo" inputmode="numeric" type="number" min="1870" max="2100" value="${e(s.filters.yearTo)}" placeholder="Любой"></label></div><label class="field"><span>Сортировка</span><select name="sort">${s.data.collection?opt('source','Порядок источника',s.filters.sort):''}${opt('newest','Сначала новые',s.filters.sort)}${opt('oldest','Сначала ранние',s.filters.sort)}${opt('title','По названию',s.filters.sort)}</select></label></form>${s.data.collection?'</details>':''}<div class="collection-tools"><label class="exclude-watched"><input type="checkbox" data-exclude-watched ${s.excludeWatched?'checked':''}> Исключить просмотренное</label><div class="collection-random"><button class="primary small" type="button" data-explore="random">${s.selection?'Ещё случайные 3':'Случайные 3 фильма'}</button>${s.selection?'<button class="secondary small" type="button" data-explore="all">Весь список</button>':''}</div><p class="help">Используется общий список просмотренного. Импорт — в «Поиск → Случайный → Мой список просмотренного».</p></div><p class="help" id="filmography-count">Показано ${Math.min(s.limit,filtered.length)} из ${filtered.length}</p><div class="filmography-cards" id="filmography-cards">${filtered.slice(0,s.limit).map(movieCard).join('')}</div><div id="filmography-more">${moreHTML()}${!filtered.length?'<p class="help">В этой фильмографии нет работ с выбранными фильтрами.</p>':''}</div><p class="sources">Источник: <a href="${e(s.data.sourceURL)}" target="_blank" rel="noopener noreferrer">${e(s.data.source)}</a>. ${s.data.collection?.edition?`Редакция ${e(s.data.collection.edition)}. `:''}${s.data.collection?.group==='popular'?'Популярная выдача Cinemeta; обновление раз в 6 часов.':s.data.person||s.data.collection?.group==='awards'?'Отдельные работы могут отсутствовать в открытых данных.':'Состав и порядок — по указанному источнику.'} ${s.data.truncated?'Источник вернул ограниченный список: фильмография может быть неполной.':''}</p>`;}
 function contents(){return `${s.error?`<p class="discover-error" role="alert">${e(s.error)}</p>`:''}${s.busy?skeletonCards('Загружаем фильмографию или подборку…'):s.data?filmography():s.mode==='people'?`<div class="explore-intro"><p class="eyebrow">ЛЮДИ, КОТОРЫЕ ДЕЛАЮТ КИНО</p><h2>Начните с имени</h2><p>Все доступные работы любимого актёра или режиссёра.</p></div><form id="person-search"><label class="field"><span>Актёр или режиссёр</span><input id="person-input" name="person" type="search" role="combobox" aria-autocomplete="list" aria-controls="person-options" aria-expanded="false" autocomplete="off" value="${e(s.query)}" placeholder="Том Хэнкс, Кристофер Нолан…" required minlength="2" maxlength="100"></label><div id="person-suggestions" class="person-suggestions"></div><button class="primary full" type="submit">Найти персону</button></form><div id="person-results">${people()}</div>${s.query&&!s.people.length&&!s.error?'<p class="help">Если имя не находится, попробуйте оригинальное написание.</p>':''}`:`<div class="explore-intro"><p class="eyebrow">НА СЕГОДНЯ И НА ПОТОМ</p><h2>Найдите своё кино</h2><p>Популярное, тематические списки и выбор критиков — с источником у каждой подборки.</p></div>${collections()}`}`;}
 function html(){return `<section id="explore-root"><div class="filters segmented" role="group" aria-label="Раздел каталога"><button class="chip" data-explore="mode" data-mode="people" aria-pressed="${s.mode==='people'}">Актёры и режиссёры</button><button class="chip" data-explore="mode" data-mode="collections" aria-pressed="${s.mode==='collections'}">Подборки</button></div><div id="explore-content">${contents()}</div></section>`;}
 function update(){const el=host();if(!el)return;const open=new Set([...el.querySelectorAll('details[open]')].map(d=>d.dataset.exploreDetail));el.querySelector('#explore-content').innerHTML=contents();for(const d of el.querySelectorAll('details'))if(open.has(d.dataset.exploreDetail))d.open=true;for(const b of el.querySelectorAll('[data-explore="mode"]'))b.setAttribute('aria-pressed',String(b.dataset.mode===s.mode));}
 function nextIds(){return visibleMovies().slice(s.limit,s.limit+12).map(m=>m.imdb_id);}
 function moreHTML(){if(!nextIds().length)return '';return '<button class="secondary outline full" type="button" data-explore="more">Показать ещё 12</button>';}
 function renderSuggestions(state){const root=host(),box=root?.querySelector('#person-suggestions'),input=root?.querySelector('#person-input');if(!box||!input)return;const open=!!(state.items.length||state.busy||state.error);input.setAttribute('aria-expanded',String(open));if(state.active>=0)input.setAttribute('aria-activedescendant','person-option-'+state.active);else input.removeAttribute('aria-activedescendant');box.innerHTML=state.busy?'<p class="help" role="status">Ищем имена…</p>':state.error?'<p class="help" role="status">'+e(state.error)+'</p>':state.items.length?`<div id="person-options" role="listbox" aria-label="Подсказки персон">${state.items.map((p,i)=>`<button type="button" role="option" id="person-option-${i}" aria-selected="${i===state.active}" data-explore="person" data-id="${e(p.id)}"><strong>${e(p.name)}</strong><span>${e(p.description)}${p.birthYear?' · '+e(p.birthYear):''}</span></button>`).join('')}</div>`:'';}
 function updateMore(){const el=host()?.querySelector('#filmography-more');if(el)el.innerHTML=moreHTML();}
 async function metadata(ids,render=true){ids=[...new Set(ids)];for(const id of ids)pending.add(id);let changed=false;try{const rows=await preloader.ensure(ids);for(const row of rows){const m=row?.movie;if(!m)continue;const current=s.movies.find(x=>x.imdb_id===m.imdb_id);if(current&&!applied.has(current)){Object.assign(current,m,{roles:current.roles,rank:current.rank,watched:current.watched||m.watched});applied.add(current);changed=true;}}return changed;}finally{for(const id of ids)pending.delete(id);if(render&&changed&&s.data)updateCards();}}
 async function warmNext(){const version=++warmVersion;warmError='';updateMore();try{const changed=await metadata(visibleMovies().slice(0,s.limit).map(m=>m.imdb_id),false);if(version!==warmVersion||!s.data)return;if(changed)updateCards();await metadata(nextIds(),false);if(version!==warmVersion||!s.data)return;updateMore();if(!preloader.isReady(nextIds()))warmNext();}catch(err){if(version===warmVersion){warmError='Не удалось подготовить следующую порцию. Нажмите, чтобы повторить.';updateMore();}}}
 function updateCards(append=false){const el=host();if(!el||!s.data)return;const list=visibleMovies(),open=new Set([...el.querySelectorAll('details[open]')].map(d=>d.dataset.exploreDetail));const random=el.querySelector('[data-explore="random"]');if(random)random.textContent=s.selection?'Ещё случайные 3':'Случайные 3 фильма';const all=el.querySelector('[data-explore="all"]');if(all)all.hidden=!s.selection;const cards=el.querySelector('#filmography-cards');if(!cards)return;const shown=[...cards.querySelectorAll('[data-movie]')].map(el=>el.dataset.movie),desired=list.slice(0,s.limit);if(append&&shown.every((id,i)=>desired[i]?.imdb_id===id))cards.insertAdjacentHTML('beforeend',desired.slice(shown.length).map(movieCard).join(''));else cards.innerHTML=desired.map(movieCard).join('');for(const d of cards.querySelectorAll('details'))if(open.has(d.dataset.exploreDetail))d.open=true;el.querySelector('#filmography-count').textContent=`Показано ${Math.min(s.limit,list.length)} из ${list.length}`;el.querySelector('#filmography-more').innerHTML=moreHTML()||(!list.length?'<p class="help">Нет работ с выбранными фильтрами.</p>':'');}
 async function load(kind,id){suggestions.cancel();const epoch=++s.epoch;s.busy=true;s.error='';update();try{const d=await request(`/api/explore/${kind}/${encodeURIComponent(id)}`);if(epoch!==s.epoch)return;s.data=d;s.movies=d.movies;s.selection=null;s.filters={role:'',kind:'',query:'',yearFrom:'',yearTo:'',sort:kind==='collection'?'source':'newest'};s.limit=12;}catch(err){if(epoch===s.epoch)s.error=err.message;}finally{if(epoch===s.epoch){s.busy=false;update();if(s.data)warmNext();}}}
 async function search(value){suggestions.cancel();const epoch=++s.epoch;s.query=value.trim();s.data=null;s.busy=true;s.error='';update();try{const d=await request('/api/explore/people?'+new URLSearchParams({query:s.query}));if(epoch!==s.epoch)return;s.people=d.people;if(!d.people.length)s.error='Персона не найдена. Попробуйте другое написание имени.';}catch(err){if(epoch===s.epoch)s.error=err.message;}finally{if(epoch===s.epoch){s.busy=false;update();}}}
 async function markSeen(id){const m=s.movies.find(m=>m.imdb_id===id);if(!m||m.watched)return;try{await request('/api/discover/seen',{method:'POST',body:{movie:m}});m.watched=true;updateCards();warmNext();}catch(err){s.error=err.message;update();}}
 function capture(form){s.selection=null;s.filters={...s.filters,...Object.fromEntries(new FormData(form))};s.limit=12;updateCards();warmNext();}
 function mount(){const el=host();if(!el)return;el.addEventListener('submit',event=>{event.preventDefault();event.stopPropagation();if(event.target.id==='person-search')search(new FormData(event.target).get('person'));});el.addEventListener('keydown',event=>{if(event.target.id!=='person-input')return;if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();suggestions.move(event.key==='ArrowDown'?1:-1);}if(event.key==='Escape'){event.preventDefault();suggestions.cancel();}if(event.key==='Enter'&&suggestions.selected()){event.preventDefault();const p=suggestions.selected();s.query=p.name;load('person',p.id);}});el.addEventListener('input',event=>{if(event.target.id==='person-input'){s.query=event.target.value;s.people=[];const results=el.querySelector('#person-results');if(results)results.innerHTML='';if(!event.isComposing)suggestions.update(event.target.value);}if(event.target.form?.id==='filmography-filters')capture(event.target.form);});el.addEventListener('change',event=>{if(event.target.matches('[data-exclude-watched]')){s.excludeWatched=event.target.checked;s.selection=null;update();warmNext();return;}if(event.target.form?.id==='filmography-filters'){capture(event.target.form);warmNext();}});el.addEventListener('error',event=>{if(event.target.matches?.('[data-explore-poster]'))event.target.hidden=true;},true);el.addEventListener('toggle',event=>{const d=event.target;if(d.matches?.('[data-explore-detail]')&&d.open)metadata([d.dataset.exploreDetail]).catch(()=>{});},true);el.addEventListener('click',event=>{const b=event.target.closest('[data-explore]');if(!b)return;const action=b.dataset.explore;if(action==='mode'){suggestions.cancel();warmVersion++;s.mode=b.dataset.mode;s.data=null;s.error='';s.epoch++;s.busy=false;update();}if(action==='person'||action==='collection'){if(action==='person'){const p=suggestions.getState().items.find(p=>p.id===b.dataset.id)||s.people.find(p=>p.id===b.dataset.id);if(p)s.query=p.name;}load(action,b.dataset.id);}if(action==='back'){warmVersion++;s.data=null;s.error='';s.epoch++;update();}if(action==='more'){s.limit+=12;updateCards(true);warmNext();}if(action==='retry-warm'){warmNext();}if(action==='random'){s.selection=randomSelection(filterFilmography(s.movies,{...s.filters,excludeWatched:s.excludeWatched}).filter(m=>m.kind!=='series')).map(m=>m.imdb_id);s.limit=12;update();warmNext();}if(action==='all'){s.selection=null;s.limit=12;update();warmNext();}if(action==='seen'){markSeen(b.dataset.id);}if(action==='want'){const m=s.movies.find(m=>m.imdb_id===b.dataset.id);if(m)onWant?.(m,b);}if(action==='release'){const m=s.movies.find(m=>m.imdb_id===b.dataset.id);if(m)onSearch(m);}});if(!collectionsLoaded){collectionsLoaded=true;request('/api/explore/collections').then(d=>{s.collections=d.collections;if(s.mode==='collections'&&!s.data&&!s.busy)update();}).catch(err=>{collectionsLoaded=false;s.error=err.message;update();});}}
 return {html,mount};
}
